#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <regex>
#include <unordered_set>
#include <algorithm>
#include <thread>
#include <mutex>
#include <sstream>
#include <iomanip>
#include <cctype>
#include <cmath>
#include <map>
#include <unordered_map>
#include <filesystem>

namespace fs = std::filesystem;

// Configuration handling
struct Config {
    std::string data_dir;
};

// Loads configuration from config.ini (simple parser)
// Looks for "data_dir" key and returns its value
// Exits program if config file or required section is missing
Config load_config() {
    Config config;
    std::ifstream config_file("config.ini");
    if (!config_file) {
        std::cerr << "Error: config.ini not found!" << std::endl;
        std::exit(1);
    }

    std::string line;
    while (std::getline(config_file, line)) {
        // Look for "data_dir = /path" format
        if (line.find("data_dir") != std::string::npos) {
            // Extract value after '='
            size_t pos = line.find('=');
            if (pos != std::string::npos) {
                config.data_dir = line.substr(pos + 1);
                // Trim whitespace
                config.data_dir.erase(0, config.data_dir.find_first_not_of(" \t"));
                config.data_dir.erase(config.data_dir.find_last_not_of(" \t") + 1);
            }
            break;
        }
    }
    return config;
}

// Cleans chat log data (removes duplicates, standardizes text)
// Takes a 2D vector of strings (each row is a CSV record)
// Returns cleaned data in same format
void clean_chat_log(std::vector<std::vector<std::string>>& data) {
    // Track seen records to remove duplicates
    std::unordered_set<std::string> seen;
    std::vector<std::vector<std::string>> cleaned;

    for (auto& row : data) {
        // Skip rows with insufficient columns
        if (row.size() < 3) continue;

        // Create unique key from timestamp, role, message
        std::string key = row[0] + "|" + row[1] + "|" + row[2];
        if (seen.find(key) != seen.end()) continue;
        seen.insert(key);

        // Standardize text: remove special chars, lowercase
        std::string& msg = row[2];
        msg = std::regex_replace(msg, std::regex("[^a-zA-Z0-9 ]"), "");
        std::transform(msg.begin(), msg.end(), msg.begin(), 
            [](unsigned char c){ return std::tolower(c); });
        cleaned.push_back(row);
    }
    data = cleaned; // Update original data
}

// Cleans transaction data (removes duplicates)
// Takes a 2D vector of strings (each row is a CSV record)
// Returns cleaned data in same format
void clean_transactions(std::vector<std::vector<std::string>>& data) {
    std::unordered_set<std::string> seen;
    std::vector<std::vector<std::string>> cleaned;

    for (auto& row : data) {
        if (row.size() < 3) continue;
        // Create unique key from timestamp, product_id, amount
        std::string key = row[0] + "|" + row[1] + "|" + row[2];
        if (seen.find(key) != seen.end()) continue;
        seen.insert(key);
        cleaned.push_back(row);
    }
    data = cleaned;
}

// Processes chat logs (with cleaning) and calculates metrics
// Returns simplified metrics (NLP skipped for C++ constraints)
std::unordered_map<std::string, double> process_chat_log(const std::string& file_path) {
    std::ifstream file(file_path);
    if (!file) {
        std::cerr << "File error: " << file_path << std::endl;
        return {};
    }

    // Read CSV into 2D vector
    std::vector<std::vector<std::string>> data;
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::vector<std::string> row;
        std::string cell;
        while (std::getline(iss, cell, ',')) {
            row.push_back(cell);
        }
        data.push_back(row);
    }

    // Clean data before processing
    clean_chat_log(data);

    // Simplified metrics (no actual NLP in C++)
    return {{"avg_response", 0.0}, {"avg_sentiment", 0.0}};
}

// Processes transaction data (with cleaning) and aggregates metrics
std::unordered_map<std::string, double> process_transactions(const std::string& file_path) {
    std::ifstream file(file_path);
    if (!file) {
        std::cerr << "File error: " << file_path << std::endl;
        return {};
    }

    // Read CSV into 2D vector
    std::vector<std::vector<std::string>> data;
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::vector<std::string> row;
        std::string cell;
        while (std::getline(iss, cell, ',')) {
            row.push_back(cell);
        }
        data.push_back(row);
    }

    // Clean data before aggregation
    clean_transactions(data);

    // Aggregate daily sales
    std::map<std::string, double> daily_sales;
    std::unordered_map<std::string, double> top_products;

    for (auto& row : data) {
        if (row.size() < 3) continue;
        // Simplified date extraction (YYYY-MM-DD format assumed)
        std::string date = row[0].substr(0, 10);
        double amount = std::stod(row[2]);
        daily_sales[date] += amount;
        top_products[row[1]] += amount;
    }

    // Get top 5 products by sales
    std::vector<std::pair<std::string, double>> top_items(top_products.begin(), top_products.end());
    std::sort(top_items.begin(), top_items.end(), 
        [](const auto& a, const auto& b) { return a.second > b.second; });

    // Return only top 5 products
    std::unordered_map<std::string, double> result;
    for (int i = 0; i < std::min(5, (int)top_items.size()); ++i) {
        result[top_items[i].first] = top_items[i].second;
    }
    return result;
}

// Main processing function for each file
// Thread-safe: uses mutex to update results
void process_file(const std::string& file_path, std::mutex& mtx, 
                 std::vector<std::string>& results) {
    // Determine if file is chat log (contains "chat" in filename)
    bool is_chat = (file_path.find("chat") != std::string::npos);
    std::unordered_map<std::string, double> metrics;

    if (is_chat) {
        metrics = process_chat_log(file_path);
    } else {
        metrics = process_transactions(file_path);
    }

    // Thread-safe update of results
    std::lock_guard<std::mutex> lock(mtx);
    results.push_back(file_path + " processed");
}

int main() {
    // Load configuration
    auto config = load_config();
    std::cout << "Starting analysis at " 
              << std::asctime(std::localtime(&std::time(nullptr))) 
              << std::endl;

    // Find all CSV files in data directory
    std::vector<std::string> files;
    for (const auto& entry : fs::directory_iterator(config.data_dir)) {
        if (entry.is_regular_file() && entry.path().extension() == ".csv") {
            files.push_back(entry.path().string());
        }
    }

    // Handle empty directory
    if (files.empty()) {
        std::cout << "No CSV files found in directory" << std::endl;
        return 0;
    }

    // Process files in parallel (4 threads)
    std::vector<std::string> results;
    std::mutex results_mutex;
    std::vector<std::thread> threads;

    for (size_t i = 0; i < files.size(); i += 4) {
        // Launch up to 4 threads per batch
        for (int j = 0; j < 4 && i + j < files.size(); ++j) {
            threads.emplace_back(process_file, files[i + j], std::ref(results_mutex), std::ref(results));
        }
        // Wait for current batch to complete
        for (auto& t : threads) t.join();
        threads.clear();
    }

    // Final output
    std::cout << "\nAnalysis completed!" << std::endl;
    std::cout << "Processed " << results.size() << " files" << std::endl;
    std::cout << "Results: " << std::endl;
    for (const auto& res : results) {
        std::cout << "  - " << res << std::endl;
    }

    return 0;
}
```

